from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]
SITE="https://jinwooson1988.github.io/tortoise-food-db-korea"
plants=json.loads((ROOT/"data/plants.json").read_text(encoding="utf-8"))
# Verdicts come from the canonical registry through the same selection/labels as the home search and the
# plant detail pages (scripts/public_verdict.py), so a guide card can never show a different grade.
import sys
sys.path.insert(0,str(Path(__file__).resolve().parent))
from public_verdict import load_assessments,by_plant,representative,display,scope_label,public_plants
assessments=load_assessments(); rows_by=by_plant(assessments)
plants=public_plants(plants,assessments)
by={p["id"]:representative(rows_by.get(p["id"],[])) for p in plants}
def e(x): return html.escape(str(x or ""),quote=True)
# One top navigation component for every secondary page (same as plant detail pages).
NAV_CSS=".detailnav{display:flex;align-items:center;margin:0 0 14px;padding:4px 2px 12px;border-bottom:1px solid var(--line);font-size:13px}.detailnavlinks{display:flex;gap:4px;align-items:center}.detailnav a,.detailnav button{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:46px;min-width:76px;padding:0 15px;border:1px solid #205c3d;border-radius:12px;background:#286a46;color:#fff;font:inherit;font-size:13px;font-weight:900;text-decoration:none;box-shadow:0 2px 8px rgba(25,85,53,.14);cursor:pointer}.detailnav a:hover,.detailnav button:hover{background:#1d5538;border-color:#17482f;color:#fff}.detailnav a:focus-visible,.detailnav button:focus-visible{outline:3px solid #a8d6b7;outline-offset:3px}"
NAV_HTML="<header class=\"detailnav\"><nav class=\"detailnavlinks\" aria-label=\"페이지 이동\"><a href=\"../../index.html\">⌂ 홈</a><button type=\"button\" onclick=\"if(history.length>1)history.back();else location.href='../../index.html'\">← 뒤로</button></nav></header>"
def cards(items):
 out=[]
 for p in items:
  a=by.get(p["id"]); g=display(a)
  out.append(f'<article class="food tone-{e(g["tone"])}"><div class="foodhead"><h3><a href="../../plant/{e(p["id"])}/">{e(p.get("ko") or p["id"])}</a></h3><span class="grade">{e(g["label"] if g["grade"]=="보류" else g["grade"]+" · "+g["label"])}</span></div><i>{e(p.get("scientific"))}</i><p>{e(g["meaning"])}</p><small>적용 범위: {e(scope_label(a))} · 근거등급: {e((a or {}).get("confidence") or "미확정")}</small><a class="more" href="../../plant/{e(p["id"])}/">판정 이유·근거 보기 →</a></article>')
 return "".join(out)
def page(slug,title,desc,items,intro):
 d=ROOT/"guides"/slug; d.mkdir(parents=True,exist_ok=True); url=f"{SITE}/guides/{slug}/"; body=cards(items); schema=json.dumps({"@context":"https://schema.org","@type":"CollectionPage","name":title,"description":desc,"url":url,"inLanguage":"ko"},ensure_ascii=False,separators=(",",":"))
 doc=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index,follow"><title>{e(title)} | 거북밥 DB</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{url}"><script type="application/ld+json">{schema}</script><style>:root{{--bg:#f4f7f3;--card:#fff;--line:#dce5dd;--text:#17231b;--muted:#647067}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);font-family:system-ui,-apple-system,"Noto Sans KR",sans-serif;color:var(--text);line-height:1.6}}main{{max-width:1180px;margin:auto;padding:22px}}a{{color:#24583a}}.hero,.note,.food{{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px;margin:12px 0}}h1{{font-size:32px;margin:6px 0}}.note{{border-left:5px solid #8a7429}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:12px}}.food{{margin:0;display:flex;flex-direction:column;gap:4px}}.foodhead{{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}}.food h3{{margin:0;font-size:19px}}.grade{{flex:none;font-weight:900;font-size:15px;padding:5px 10px;border-radius:999px;border:1px solid var(--line);background:#f7faf7}}.tone-green .grade{{background:#e3f3e8;border-color:#a9d5b6;color:#155a31}}.tone-teal .grade{{background:#e2f2f1;border-color:#a7d3cf;color:#145b55}}.tone-yellow .grade{{background:#fbf3d9;border-color:#e6d08c;color:#6b5310}}.tone-danger .grade{{background:#fbe5e2;border-color:#e6aaa1;color:#8a2a1d}}.tone-hold .grade{{background:#eef0f2;color:#4a5560}}.food p{{margin:4px 0;font-weight:650}}.food .more{{display:inline-flex;align-items:center;min-height:44px;font-weight:800}}small,i{{color:var(--muted)}}@media(max-width:760px){{main{{padding:14px}}.grid{{grid-template-columns:1fr}}}}{NAV_CSS}</style></head><body><main>{NAV_HTML}<section class="hero"><h1>{e(title)}</h1><p>{e(intro)}</p></section><section class="note"><b>읽는 법</b><br>이 페이지는 DB의 기존 판정을 주제별로 모아 보여주는 탐색 허브다. 목록에 포함됐다는 사실 자체가 급여 권장을 뜻하지 않는다. 각 항목의 판정·적용 범위·근거등급을 확인하고 상세 페이지에서 근거와 한계를 함께 확인한다.</section><div class="grid">{body}</div><section class="note"><b>근거 해석 원칙</b><br>야생 섭식 관찰은 사육 배합률이 아니며, 일반 초식 파충류 자료는 지중해 육지거북(Testudo속)을 직접 다룬 근거와 같지 않다. 근거 부족을 안전으로 간주하지 않는다.</section></main></body></html>'''
 (d/"index.html").write_text(doc,encoding="utf-8"); return url
market=[p for p in plants if any(x in (p.get("market") or "") for x in ("마트","시장","온라인"))]
wild=[p for p in plants if p.get("category")=="wild" or "채집" in (p.get("market") or "")]
caution=[p for p in plants if display(by.get(p["id"]))["grade"] in {"C","D","보류"} or p.get("identity_status")!="verified_name"]
research_slug="research-method"
research_dir=ROOT/"guides"/"research-method"
research_dir.mkdir(parents=True,exist_ok=True)
research_url=f"{SITE}/guides/research-method/"
research_schema=json.dumps({"@context":"https://schema.org","@type":"WebPage","name":"거북밥 판정·근거 검토 방법","description":"거북밥이 식물 급여 판정을 만들고 근거의 범위와 한계를 표시하는 방법.","url":research_url,"inLanguage":"ko"},ensure_ascii=False,separators=(",",":"))
research_doc=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index,follow"><title>거북밥 판정·근거 검토 방법 | 거북밥 DB</title><meta name="description" content="거북밥이 식물 급여 판정을 만들고 근거의 범위와 한계를 표시하는 방법."><link rel="canonical" href="{research_url}"><script type="application/ld+json">{research_schema}</script><style>:root{{--bg:#f5f8f5;--card:#fff;--line:#dbe6dd;--text:#17251c;--muted:#627067;--accent:#205d3b;--soft:#eef5ef}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);font-family:system-ui,-apple-system,"Noto Sans KR",sans-serif;color:var(--text);line-height:1.65}}main{{max-width:920px;margin:auto;padding:24px 18px 50px}}a{{color:var(--accent)}}.hero,.card,.note{{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:20px;margin:12px 0}}h1{{font-size:34px;line-height:1.25;margin:8px 0}}h2{{font-size:20px;margin:0 0 8px}}.eyebrow{{font-size:11px;font-weight:900;letter-spacing:.12em;color:var(--accent)}}.note{{background:var(--soft)}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:12px}}.label{{font-weight:900;color:var(--accent)}}ul{{padding-left:20px}}.sources a{{display:block;margin:7px 0}}small{{color:var(--muted)}}@media(max-width:700px){{main{{padding:14px}}.grid{{grid-template-columns:1fr}}h1{{font-size:28px}}}}{NAV_CSS}</style></head><body><main>{NAV_HTML}<section class="hero"><div class="eyebrow">EVIDENCE & REVIEW</div><h1>거북밥은 어떻게 판정하는가?</h1><p>검색 결과의 A·B·C·D는 ‘인터넷에서 많이 먹인다는 말’을 단순히 모은 등급이 아니다. 식물의 정확한 정체성, 실제 확인된 식물 부위, 근거가 다루는 동물 분류군과 자료의 성격을 분리해 검토한 뒤 공개한다.</p></section><section class="grid"><article class="card"><h2>1. 식물부터 정확히 확인</h2><p>학명과 분류계급을 우선 확인한다. 종을 확정할 수 없는 자료를 다른 종의 대표 이미지나 근거로 조용히 치환하지 않는다.</p></article><article class="card"><h2>2. ‘무슨 부위인가’를 분리</h2><p>잎·꽃·열매·뿌리·씨앗 등은 서로 같은 급여 근거로 자동 취급하지 않는다. 사진과 급여 대상 부위가 다르면 상세페이지에서 그 차이를 표시한다.</p></article><article class="card"><h2>3. 근거의 적용 범위를 확인</h2><p>육지거북 직접 자료, 전문 사육자료, 근연 분류군 자료, 일반 초식 파충류 자료, 식물 성분·독성 자료를 같은 무게로 섞지 않는다. 어떤 자료가 무엇을 말할 수 있는지 함께 표시한다.</p></article><article class="card"><h2>4. 근거가 약하면 약하다고 표시</h2><p>야생에서 먹었다는 관찰은 ‘자연에서 섭식됐다’는 사실을 보여줄 수 있지만 사육장에서의 권장 급여 비율을 자동으로 결정하지 않는다. 근거 부족을 안전하다고 해석하지 않는다.</p></article></section><section class="note"><h2>판정의 핵심</h2><p><span class="label">직접 근거가 가장 강한가?</span> → 대상 거북과 식물을 실제로 다룬 자료인지 확인한다.</p><p><span class="label">다른 자료라면 무엇을 보완하는가?</span> → 수의학·전문 사육·야생생태·식물학·성분 자료의 역할을 구분한다.</p><p><span class="label">무엇을 아직 모르는가?</span> → 확인되지 않은 종·부위·용량·장기 영향은 확정된 사실처럼 쓰지 않는다.</p></section><section class="card sources"><h2>검토 체계를 참고한 주요 공개 자료</h2><small>거북밥의 판정은 각 항목의 원자료와 데이터 상태를 기준으로 하며, 아래 자료는 연구·사육 정보의 검토 원칙을 이해하기 위한 공개 참고자료다.</small><a href="https://www.thetortoisetable.org.uk/resources/how-we-do-our-research/">The Tortoise Table — How we do our Research</a><a href="https://www.merckvetmanual.com/management-and-nutrition/nutrition-exotic-and-zoo-animals/nutrition-in-tortoises">Merck Veterinary Manual — Nutrition in Tortoises</a><a href="https://www.rvc.ac.uk/Media/Default/Beaumont%20Sainsbury%20Animal%20Hospital/EXOTICS/Animal%20Care%20Factsheets/Mediterranean%20tortoise%20care%202024%20jh.pdf">Royal Veterinary College — Mediterranean Tortoise Care</a><div class="source-expansion"><h3>공식 영양성분 원자료</h3><p>아래는 실제 영양자료 조사에 사용된 국가별 공식 데이터베이스다. 특정 식물의 수치 채택 여부는 각 식물 상세페이지에서 확인한다.</p><a href="https://fdc.nal.usda.gov/" target="_blank" rel="noopener noreferrer">미국 USDA — FoodData Central</a><a href="https://www.mext.go.jp/a_menu/syokuhinseibun/mext_00001.html" target="_blank" rel="noopener noreferrer">일본 MEXT — 일본 식품표준성분표</a><a href="https://nin.res.in/ebooks/IFCT2017.pdf" target="_blank" rel="noopener noreferrer">인도 ICMR-NIN — Indian Food Composition Tables</a><h3>추가 조사 중인 국제 자료</h3><p>아래는 글로벌 조사 대상이다. 모든 자료가 개별 식물의 급여 판정에 사용됐다는 의미는 아니다.</p><a href="https://www.fao.org/food-composition/tables-and-databases/" target="_blank" rel="noopener noreferrer">FAO/INFOODS — 세계 식품성분 데이터베이스 안내</a><a href="https://www.anses.fr/en/content/ciqual-nutritional-composition-table" target="_blank" rel="noopener noreferrer">프랑스 ANSES — Ciqual</a><a href="https://frida.fooddata.dk/" target="_blank" rel="noopener noreferrer">덴마크 DTU — Frida</a><p>일반 사육 커뮤니티 경험은 검증된 학술 근거와 분리해 수집하며, 공식 급여 등급을 결정하지 않는다.</p></div></section></main></body></html>'''
(research_dir/"index.html").write_text(research_doc,encoding="utf-8")
urls=[page("market-foods","마트에서 구할 수 있는 육지거북 먹이","마트·시장·온라인에서 찾기 쉬운 육지거북 먹이를 DB 판정과 근거 범위로 비교한다.",market,"한국에서 실제로 구하기 쉬운 먹이를 모았다. 편의성보다 종 동정과 근거 수준을 우선해 판단한다."),page("wild-plants","육지거북 야생초·채집 식물","민들레·질경이 등 육지거북 야생초와 채집 식물의 판정, 적용 범위와 근거를 확인한다.",wild,"야생초는 자연식이라는 이유만으로 자동 안전하지 않다. 식물 동정, 오염 가능성, 대상 종에 대한 근거를 함께 확인한다."),page("caution-foods","육지거북 급여 주의 식물","제한적 보조근거·일반 파충류 근거·동정 주의가 필요한 육지거북 먹이를 구분해 확인한다.",caution,"‘먹을 수 있음’과 ‘주식으로 적합함’을 분리한다. 직접 근거가 약하거나 적용 범위가 좁은 항목을 우선 확인한다.")]
s=ROOT/"sitemap.xml"; txt=s.read_text(encoding="utf-8")
urls.append(research_url)
for u in urls:
 tag=f'  <url><loc>{u}</loc><lastmod>2026-09-19</lastmod></url>\n'
 if u not in txt: txt=txt.replace("</urlset>",tag+"</urlset>")
s.write_text(txt,encoding="utf-8")
print("generated guide hubs",len(market),len(wild),len(caution))
